  const readSubcommands = async (category) => {
    const stdout = createBufferStream();
    const stderr = createBufferStream();
    const exitCode = await runCli({
      argv: [category, "--help"],
      runtime: createRuntime(),
      stdout: stdout.stream,
      stderr: stderr.stream,
