   176	git --git-dir=/tmp/mirror worktree add /tmp/run /tmp/mirror/main
   177	docker run -it --rm -e GH_TOKEN="$GH_TOKEN" -v "$HOME/.pi:/home/node/.pi" -v /tmp/run:/workspace dev-loops pi
