    48	  /** Review feedback fix/reply/resolve loop. */
    49	  FEEDBACK_RESOLUTION: "feedback_resolution",
    50	  /** Pre-approval gate before merge. */
    51	  PRE_APPROVAL_GATE: "pre_approval_gate",
    52	  /** Final merge step. */
