   143	/**
   144	 * Map an explicit lifecycle phase string to its canonical state value.
   145	 * Returns the canonical state if recognized, otherwise null.
   146	 */
   147	function normalizeLifecycleState(value) {
   148	  if (typeof value !== "string") return null;
   149	  const trimmed = value.trim().toLowerCase();
   150	  return LIFECYCLE_STATE_SET.has(trimmed) ? trimmed : null;
