   152	
   153	/**
   154	 * Resolve the current lifecycle phase from authoritative inputs.
   155	 *
   156	 * Input shape:
   157	 * ```js
   158	 * {
   159	 *   phase,              // explicit phase string (overrides infer)
   160	 *   hasLinkedPr,        // boolean: open linked PR exists
   161	 *   prIsDraft,          // boolean: PR is in draft state
   162	 *   hasUnresolvedThreads, // boolean: unresolved review threads exist
   163	 *   preApprovalGatePassed, // boolean: current-head pre_approval_gate clean
   164	 *   mergeAuthorized,    // boolean: explicit merge authorization granted
   165	 *   humanMergeOnly,     // boolean: repo invariant — agent may never merge (fails closed)
   166	 *   isMerged,           // boolean: PR has been merged
   167	 * }
   168	 * ```
   169	 *
   170	 * Returns:
   171	 * ```js
   172	 * {
   173	 *   state: string,              // canonical lifecycle phase
   174	 *   allowedTransitions: string[], // legal next phases
   175	 *   nextAction: string,         // recommended next action
   176	 *   isTerminal: boolean,        // true if merge (no further progression)
   177	 * }
   178	 * ```
   179	 *
   180	 * Resolution order (first-match):
   181	 * 1. Explicit phase → return canonical if recognized, fall through if not
   182	 * 2. Merged → merge (terminal)
   183	 * 3. Merge authorized + pre-approval passed + linked PR → merge
   184	 * 4. Pre-approval passed + PR exists → pre_approval_gate
   185	 * 5. Unresolved threads + PR exists → feedback_resolution
   186	 * 6. Draft PR → implementation
   187	 * 7. Ready PR (not draft) → implementation
   188	 * 8. No linked PR → issue_intake
   189	 */
   190	export function resolveLifecycleState(input = {}) {
   191	  const {
   192	    phase = null,
   193	    hasLinkedPr = false,
   194	    prIsDraft = false,
   195	    hasUnresolvedThreads = false,
   196	    preApprovalGatePassed = false,
   197	    mergeAuthorized = false,
   198	    humanMergeOnly = false,
   199	    isMerged = false,
   200	  } = input;
   201	
   202	  // Fail closed: when the repo enforces human-only merge, the agent is never
   203	  // cleared to advance to the merge action — the per-run mergeAuthorized signal
   204	  // is ignored. Also fail closed on a non-boolean `mergeAuthorized` (only an
   205	  // exact `true` clears merge), matching the authoritative
   206	  // `resolveEffectiveMergeAuthorized` gate. An already-merged PR (isMerged) is
   207	  // still terminal below.
   208	  const effectiveMergeAuthorized = humanMergeOnly !== true && mergeAuthorized === true;
   209	
   210	  // 1. Explicit phase override — canonical or fail closed
   211	  if (phase !== null && phase !== undefined) {
   212	    const normalized = normalizeLifecycleState(phase);
   213	    if (normalized) {
   214	      return buildResult(normalized);
   215	    }
   216	    // unrecognized phase: fall through to inference
   217	  }
   218	
   219	  // 2. Merged → terminal
   220	  if (isMerged) {
   221	    return buildResult(LIFECYCLE_STATE.MERGE);
   222	  }
   223	
   224	  // 3. Merge authorized with pre-approval + linked PR → merge
   225	  // (humanMergeOnly forces effectiveMergeAuthorized=false above, so the loop
   226	  // stays at the pre_approval_gate human-merge handoff instead.)
   227	  if (effectiveMergeAuthorized && preApprovalGatePassed && hasLinkedPr) {
   228	    return buildResult(LIFECYCLE_STATE.MERGE);
   229	  }
   230	
   231	  // 4. Pre-approval gate passed (but merge not yet authorized)
   232	  if (preApprovalGatePassed && hasLinkedPr) {
   233	    return buildResult(LIFECYCLE_STATE.PRE_APPROVAL_GATE);
   234	  }
