     1	/**
     2	 * Neutral run-id / async-context contract.
     3	 *
     4	 * The dev-loop async path keys off the harness-neutral `DEVLOOPS_RUN_ID` env var to
     5	 * identify an inspectable per-subagent run (runner ownership, async-start enforcement,
     6	 * human-comment gating), and provides a mint-and-propagate path for harnesses (e.g. Claude
     7	 * Code) that inject no native per-subagent run id. For those harnesses dev-loops itself mints
     8	 * and sets `DEVLOOPS_RUN_ID` when dispatching an async subagent.
     9	 *
    10	 * Other harnesses may already inject their own run-id var: the Pi runtime injects
    11	 * `PI_SUBAGENT_RUN_ID` (not `DEVLOOPS_RUN_ID`) into each async subagent's child env, so that
    12	 * name is honored as a recognized run-id alias (precedence after the neutral primary). It is
    13	 * an externally-injected Pi-runtime contract var, not a dev-loops-owned var — dev-loops still
    14	 * mints/propagates only the neutral `DEVLOOPS_RUN_ID`.
    15	 *
    16	 * This module is pure except for the explicit file/IO helpers (writeRunContext/readRunContext),
    17	 * which take an injectable `fs` and `root` for testability.
    18	 */
    19	
    20	import crypto from "node:crypto";
    21	import fsDefault from "node:fs";
    22	import path from "node:path";
    23	
    24	/**
    25	 * Env var names that carry the async-context run id, in resolution precedence order.
    26	 * The neutral `DEVLOOPS_RUN_ID` is primary; `PI_SUBAGENT_RUN_ID` is the alias the Pi
    27	 * runtime injects into async-subagent child envs (the only run-id marker present under Pi).
    28	 */
    29	export const RUN_ID_MARKERS = Object.freeze(["DEVLOOPS_RUN_ID", "PI_SUBAGENT_RUN_ID"]);
    30	
    31	/** Neutral env var name used when minting/propagating a run id. */
    32	export const NEUTRAL_RUN_ID_VAR = "DEVLOOPS_RUN_ID";
    33	
    34	/** State-file name (under `.pi/`, consistent with existing dev-loop checkpoint files). */
    35	export const RUN_CONTEXT_FILENAME = "dev-loop-run-context.json";
    36	
    37	/**
    38	 * Env var Claude Code sets in every tool/subagent shell it spawns.
    39	 * Used as the harness signal — see `isClaudeHarness`.
    40	 */
    41	export const CLAUDE_HARNESS_MARKER = "CLAUDECODE";
    42	
    43	/**
    44	 * True when running under the Claude Code harness.
    45	 *
    46	 * Claude Code sets `CLAUDECODE=1` in the environment of every Bash tool and
    47	 * subagent it spawns. This is the harness-detection seam used to relax
    48	 * Pi-specific runtime contracts (e.g. the async-start contract) that do not
    49	 * apply to Claude's execution model.
    50	 *
    51	 * @param {Record<string, string|undefined>} [env]
    52	 * @returns {boolean}
    53	 */
    54	export function isClaudeHarness(env = process.env) {
    55	  return env?.[CLAUDE_HARNESS_MARKER] === "1";
    56	}
    57	
    58	/**
    59	 * Resolve the active run id from the environment.
    60	 *
    61	 * @param {Record<string, string|undefined>} [env]
    62	 * @returns {string|null} The trimmed run id, or null when none is set.
    63	 */
    64	export function resolveRunId(env = process.env) {
    65	  for (const marker of RUN_ID_MARKERS) {
    66	    const value = env?.[marker];
    67	    if (typeof value === "string" && value.trim().length > 0) {
    68	      return value.trim();
    69	    }
    70	  }
    71	  return null;
    72	}
    73	
    74	/**
    75	 * Mint a fresh neutral run id.
    76	 *
    77	 * @returns {string} `devloops-<uuid>` (e.g. "devloops-3f2c1e84-...-9a0b")
    78	 */
    79	export function mintRunId() {
    80	  return `devloops-${crypto.randomUUID()}`;
    81	}
    82	
    83	/**
    84	 * Build the env fragment that propagates a run id to child processes.
    85	 *
    86	 * Sets the neutral var; child Bash scripts observe it via `resolveRunId`. Callers merge
    87	 * this into the child env (e.g. `{ ...process.env, ...runContextEnv(runId) }`).
    88	 *
    89	 * @param {string} runId
    90	 * @returns {{ DEVLOOPS_RUN_ID: string }}
    91	 */
    92	export function runContextEnv(runId) {
    93	  return { [NEUTRAL_RUN_ID_VAR]: runId };
    94	}
    95	
    96	/**
    97	 * Absolute path to the run-context state file for a repo root.
    98	 *
    99	 * @param {string} root - Repository root (or any base dir).
   100	 * @returns {string}
   101	 */
   102	export function runContextPath(root) {
   103	  return path.join(root, ".pi", RUN_CONTEXT_FILENAME);
   104	}
   105	
   106	/**
   107	 * Persist the run-context state file (for inspection/recovery).
   108	 *
   109	 * @param {object} params
   110	 * @param {string} params.runId
   111	 * @param {string} params.root
   112	 * @param {string} [params.mintedAt] - ISO timestamp; defaults to now. Tests pass a fixed
   113	 *   value for determinism; real runs get a useful inspection/recovery timestamp.
   114	 * @param {typeof import("node:fs")} [params.fs]
   115	 * @returns {string} The path written.
   116	 */
   117	export function writeRunContext({ runId, root, mintedAt, fs = fsDefault }) {
   118	  if (typeof runId !== "string" || runId.trim().length === 0) {
   119	    throw new TypeError("writeRunContext: runId must be a non-empty string");
   120	  }

